   190→            gas_limit,
   191→            to,
   192→            value,
   193→            input,
   194→            max_fee_per_gas,
   195→            max_priority_fee_per_gas,
   196→            access_list,
   197→        } = tx;
   198→        Self {
   199→            tx_type: tx.ty(),
   200→            caller,
   201→            gas_limit: *gas_limit,
   202→            gas_price: *max_fee_per_gas,
   203→            kind: *to,
   204→            value: *value,
   205→            data: input.clone(),
   206→            nonce: *nonce,
   207→            chain_id: Some(*chain_id),
   208→            gas_priority_fee: Some(*max_priority_fee_per_gas),
   209→            access_list: access_list.clone(),
   210→            ..Default::default()
   211→        }
   212→    }
   213→}
   214→
   215→impl FromTxWithEncoded<TxEip1559> for TxEnv {
   216→    fn from_encoded_tx(tx: &TxEip1559, sender: Address, _encoded: Bytes) -> Self {
   217→        Self::from_recovered_tx(tx, sender)
   218→    }
   219→}
