   222→    fn from_recovered_tx(tx: &TxEip4844, caller: Address) -> Self {
   223→        let TxEip4844 {
   224→            chain_id,
   225→            nonce,
   226→            gas_limit,
   227→            to,
   228→            value,
   229→            input,
   230→            max_fee_per_gas,
   231→            max_priority_fee_per_gas,
